    "priority": "Medium",
    "preconditions": "Non-production tenant or isolated local fixture; synthetic records only; Use a versioned synthetic fixture with a verified baseline snapshot.",
    "test_steps": "1. Prepare a disposable, versioned synthetic fixture: Use a versioned synthetic fixture with a verified baseline snapshot. 2. Execute the operation to run a multi-task DAG only after all declared upstream dependencies succeed. 3. Capture the committed result, version or workflow state, and audit evidence. 4. Compare output with the source fixture and the expected invariant. 5. Repeat the operation where applicable and verify recovery, access, and side-effect behavior.",
